  "implementation": "def solve(case):
    import math
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Validate all nodes in core_distance
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f'Missing core distance for node {node}')

    # Build edges list
    edges = []
    for a, b, d in distances:
        if a not in nodes or b not in nodes:
            raise ValueError(f'Edge endpoints {a}, {b} not in nodes')
        # Canonicalize undirected endpoints
        u, v = (a, b) if a <= b else (b, a)
        weight = max(core_distance[u], core_distance[v], d)
        edges.append((weight, u, v))

    # Sort by weight, then by node IDs
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    selected = []
    total_weight = 0.0
    n = len(nodes)
    target_edges = n - 1

    for weight, u, v in edges:
        if union(u, v):
            selected.append([u, v, weight])
            total_weight += weight
            if len(selected) == target_edges:
                break

    if len(selected) != target_edges:
        raise ValueError('Graph is disconnected')

    # Return in required format
    return {'mst_edges': selected, 'total_weight': total_weight}"
